#!/usr/bin/env python3
"""Machine-verification of the algebra worksheet answer key.

For each problem in problems.json:
  1. Parse the rendered equation text into a syntax tree.
  2. Substitute the claimed answer back in for x.
  3. Assert that both sides evaluate to the same value.
"""

import argparse
import ast
import json


class _Eval(ast.NodeVisitor):
    """Evaluate an arithmetic AST with x bound to a value."""

    def __init__(self, x):
        self.x = x

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_BinOp(self, node):
        left, right = self.visit(node.left), self.visit(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError(f"unsupported operator: {ast.dump(node.op)}")

    def visit_UnaryOp(self, node):
        val = self.visit(node.operand)
        if isinstance(node.op, ast.USub):
            return -val
        if isinstance(node.op, ast.UAdd):
            return val
        raise ValueError(f"unsupported unary operator: {ast.dump(node.op)}")

    def visit_Constant(self, node):
        if not isinstance(node.value, (int, float)):
            raise ValueError(f"non-numeric constant: {node.value!r}")
        return node.value

    def visit_Name(self, node):
        if node.id == "x":
            return self.x
        raise ValueError(f"unknown variable: {node.id}")

    def generic_visit(self, node):
        raise ValueError(f"unexpected node: {type(node).__name__}")


def parse_side(expr):
    """Parse one side of an equation into an evaluatable AST.

    Handles implicit multiplication like '3x' and '4(...)'.
    """
    expr = expr.replace(" ", "")
    # Insert explicit multiplication operators.
    out = []
    for i, ch in enumerate(expr):
        out.append(ch)
        nxt = expr[i + 1] if i + 1 < len(expr) else ""
        if ch.isdigit() and (nxt == "x" or nxt == "("):
            out.append("*")
    return ast.parse("".join(out), mode="eval")


def check_problem(problem):
    """Substitute the answer back into the parsed equation; return bool."""
    lhs_text, rhs_text = problem["text"].split("=")
    evaluator = _Eval(problem["answer"])
    lhs = evaluator.visit(parse_side(lhs_text))
    rhs = evaluator.visit(parse_side(rhs_text))
    return lhs == rhs


def main():
    ap = argparse.ArgumentParser(description="Verify algebra answer key.")
    ap.add_argument("-f", "--file", default="problems.json")
    args = ap.parse_args()

    with open(args.file) as f:
        problems = json.load(f)

    failures = []
    for p in problems:
        if not check_problem(p):
            failures.append(p)

    for p in failures:
        print(f"FAIL id={p['id']}: {p['text']} (claimed answer {p['answer']})")

    total = len(problems)
    print(f"{total - len(failures)}/{total} problems verified.")
    if failures:
        raise SystemExit(1)


if __name__ == "__main__":
    main()

