"""Pytest suite: seeds 0-9, N=25."""

import json

import pytest

from gen_algebra import generate_problems
from verify_algebra import check_problem

SEEDS = list(range(10))
N = 25


@pytest.fixture(params=SEEDS)
def problems(request):
    return generate_problems(request.param, N)


def test_verification_passes(problems):
    for p in problems:
        assert check_problem(p), f"id={p['id']}: {p['text']} vs answer {p['answer']}"


def test_answers_in_range_and_nonzero(problems):
    for p in problems:
        assert isinstance(p["answer"], int)
        assert -9 <= p["answer"] <= 9
        assert p["answer"] != 0


def test_both_kinds_appear(problems):
    kinds = {p["kind"] for p in problems}
    assert "ax + b = c" in kinds
    assert "a(x + b) = c" in kinds


def test_text_never_contains_plus_minus(problems):
    for p in problems:
        assert "+ -" not in p["text"], f"id={p['id']}: {p['text']}"


def test_schema():
    for p in generate_problems(0, N):
        assert set(p.keys()) == {"id", "kind", "text", "answer"}
        assert p["text"].count("=") == 1


def test_json_round_trip(tmp_path):
    path = tmp_path / "problems.json"
    problems = generate_problems(7, N)
    path.write_text(json.dumps(problems))
    loaded = json.loads(path.read_text())
    assert loaded == problems
    assert all(check_problem(p) for p in loaded)

